-- Explicações por artigo — Decreto da Pensão Especial aos Órfãos de Vítimas de Feminicídio. Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pensão especial instituída pela Lei nº 14.717, de 31 de outubro de 2023, é a garantia de um salário mínimo mensal aos filhos e aos dependentes menores de dezoito anos na data do óbito de mulher vítima de feminicídio, cuja renda familiar mensal per capita seja igual ou inferior a 1/4 do salário mínimo. Para a pensão, considera-se família a unidade de pessoas que contribuam para o rendimento ou tenham despesas atendidas pela unidade e habitem o mesmo domicílio no requerimento; renda familiar mensal a soma dos rendimentos brutos de todos os membros; renda per capita a razão entre a renda e o total de indivíduos; dependente o enteado, a criança ou o adolescente menor de dezoito anos sob guarda ou tutela da vítima, com dependência econômica comprovada; e representante legal quem é legalmente responsável pelo órgão, com termo ou certidão judicial.', '["Pensão especial de um salário mínimo mensal.","Beneficiários: filhos e dependentes menores de dezoito anos na data do óbito.","Renda familiar per capita de até 1/4 do salário mínimo.","Conceitos de família, renda, dependente e representante legal."]'::jsonb, '["Requisito de renda: até 1/4 do salário mínimo per capita.","Dependente exige comprovação de dependência econômica."]'::jsonb, 'O filho de dez anos de uma mulher vítima de feminicídio, em família de baixa renda, tem direito à pensão.', '["Assertiva que dispensa o limite de renda para a pensão especial erra: o limite per capita é de 1/4 do salário mínimo."]'::jsonb, '[{"termo":"Feminicídio","significado":"Homicídio de mulher por razões da condição de sexo feminino."}]'::jsonb, '["Art. 121-A do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pensão especial também será devida a crianças e adolescentes órfãos que estejam sob a tutela do Estado. Nesse caso, a pensão será depositada em conta bancária destinada a essa finalidade, que só poderá ser movimentada quando a criança ou o adolescente for reintegrado em família ampliada, colocado em família substituta ou completar dezoito anos, salvo decisão judicial que autorize a movimentação.', '["Órfãos sob a tutela do Estado também têm direito.","Depósito em conta bancária específica.","Movimentação: reintegração em família ampliada, família substituta ou dezoito anos."]'::jsonb, '["A conta só é movimentada nas hipóteses do parágrafo único, ou por decisão judicial."]'::jsonb, 'A criança acolhida em abrigo recebe a pensão em conta bloqueada até ser colocada em família substituta.', '["Assertiva que permite a livre movimentação imediata da conta do órfão sob tutela do Estado erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pensão especial não gera direito a abono anual e não está sujeita a descontos.', '["Sem abono anual (13º).","Não sofre descontos."]'::jsonb, '["Sem abono anual."]'::jsonb, 'O beneficiário recebe o valor mensal integral, mas sem décimo terceiro.', '["Assertiva que prevê abono anual na pensão especial erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
