insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pensão especial não é acumulável com benefícios previdenciários recebidos do Regime Geral de Previdência Social ou dos Regimes Próprios de Previdência Social, nem com pensões ou benefícios do sistema de proteção social dos militares, ressalvado o direito de opção.', '["Vedada a acumulação com benefícios previdenciários.","Vale para RGPS, regimes próprios e sistema dos militares.","Direito de opção."]'::jsonb, '["Vedada a acumulação, mas há direito de OPÇÃO."]'::jsonb, 'O beneficiário que recebe pensão por morte do INSS deve optar por um dos benefícios.', '["Assertiva que permite acumular a pensão especial com pensão por morte do INSS erra: há vedação, com direito de opção."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabe ao Instituto Nacional do Seguro Social (INSS) receber e processar os requerimentos e decidir quanto à concessão da pensão. O requerimento será realizado por meio dos canais de atendimento do INSS.', '["INSS recebe, processa e decide.","Requerimento pelos canais do INSS."]'::jsonb, '["Quem decide é o INSS."]'::jsonb, 'O representante legal pede a pensão pelo atendimento do INSS.', '["Assertiva que atribui a concessão ao Ministério da Justiça erra: é do INSS."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São requisitos para a concessão, a manutenção e a revisão da pensão a inscrição regular no CPF; a apresentação de documento oficial com foto da criança ou do adolescente ou, na impossibilidade, a certidão de nascimento; a inscrição e a atualização, a cada vinte e quatro meses, no Cadastro Único, com o CPF do requerente e de todos os membros da família; e a apresentação de um documento que relacione o fato a um feminicídio, como o auto de prisão em flagrante, o decreto de prisão preventiva, a portaria inaugural do inquérito, o relatório do inquérito, a denúncia, decisão cautelar ou de mérito ou a sentença condenatória transitada em julgado. Se for dependente, deve apresentar também o termo de guarda ou de tutela ou outro documento de dependência. As equipes socioassistenciais orientarão as famílias a atualizar o CadÚnico.', '["CPF regular.","Documento oficial com foto ou certidão de nascimento.","CadÚnico atualizado a cada vinte e quatro meses.","Documento que ligue o fato ao feminicídio (sete opções).","Dependente: termo de guarda ou tutela."]'::jsonb, '["A comprovação do feminicídio NÃO exige sentença condenatória: vários documentos servem.","Atualização do CadÚnico a cada vinte e quatro meses."]'::jsonb, 'O auto de prisão em flagrante basta para relacionar o fato ao feminicídio.', '["Assertiva que exige sentença transitada em julgado para conceder a pensão erra: há outros documentos válidos."]'::jsonb, '[{"termo":"CadÚnico","significado":"Cadastro Único para Programas Sociais do Governo Federal."}]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o INSS identificar pendências quanto aos requisitos, comunicará ao requerente para regularizar a instrução. O requerente terá noventa dias, contados do recebimento da comunicação. Esgotado o prazo sem apresentação dos documentos, o processo será decidido no mérito com base nas informações constantes e nos sistemas do INSS ou encerrado, sem análise do mérito, após o prazo.', '["INSS comunica as pendências.","Prazo de noventa dias para regularizar.","Depois do prazo: decisão pelo conteúdo disponível ou encerramento sem análise do mérito."]'::jsonb, '["Prazo de noventa dias."]'::jsonb, 'O requerente recebe a comunicação do INSS e tem noventa dias para completar os documentos.', '["Assertiva que fixa em trinta dias o prazo para regularizar erra: são noventa dias."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para requerer a pensão, o representante legal deverá apresentar ao INSS documento pessoal com cadastro biométrico; o CPF; documento que comprove a relação do filho ou dependente com a vítima; documento que comprove a qualidade de representante legal; e um dos documentos que relacionem o fato a um feminicídio. O representante estrangeiro residente que não tiver o documento biométrico poderá usar a Carteira de Registro Nacional Migratório. É vedada a representação pelo autor, coautor ou partícipe do crime. As crianças em serviço de acolhimento poderão ser representadas pelos dirigentes das instituições.', '["Documentos do representante legal.","Estrangeiro: Carteira de Registro Nacional Migratório até a validação biométrica.","Vedada a representação pelo autor, coautor ou partícipe do crime.","Dirigente da instituição representa crianças acolhidas."]'::jsonb, '["O autor do crime NÃO pode representar os filhos para receber a pensão."]'::jsonb, 'A avó guardiã apresenta o termo de guarda e requer a pensão pelos netos.', '["Assertiva que permite ao autor do feminicídio representar os filhos erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 1º, §1º, V"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Havendo mais de um filho ou dependente da vítima, a pensão será dividida em partes iguais entre os elegíveis. Cessando o direito de uma das partes, a cota é convertida em favor dos demais. A concessão não será postergada pela falta de requerimento de outro possível beneficiário, e qualquer habilitação posterior só produz efeito a contar do requerimento.', '["Divisão em partes iguais.","Reversão da cota aos demais quando uma parte cessa.","Concessão não é adiada por falta de requerimento de outro beneficiário.","Habilitação posterior vale a partir do requerimento."]'::jsonb, '["Cota que cessa REVERTE aos demais beneficiários."]'::jsonb, 'Com dois filhos, cada um recebe metade, e se um completa dezoito anos o outro passa a receber o total.', '["Assertiva que extingue a cota do beneficiário cessante sem reversão erra: ela se converte em favor dos demais."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não serão computados como renda familiar mensal os benefícios e auxílios assistenciais de natureza eventual e temporária; os valores de programas assistenciais de transferência de renda, com exceção do benefício de prestação continuada; e as rendas de natureza eventual ou sazonal.', '["Benefícios eventuais e temporários não contam.","Programas de transferência de renda não contam, exceto o BPC.","Rendas eventuais ou sazonais não contam."]'::jsonb, '["O BPC CONTA como renda; outros programas assistenciais não."]'::jsonb, 'O valor de um auxílio emergencial temporário não entra na renda familiar.', '["Assertiva que exclui o BPC do cálculo da renda erra: ele é computado."]'::jsonb, '[]'::jsonb, '["Art. 1º, §1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os filhos e dependentes menores de dezoito anos na data de publicação da Lei nº 14.717, de 31 de outubro de 2023, terão direito à pensão, sem efeitos financeiros retroativos, ainda que o feminicídio tenha ocorrido antes. O filho ou dependente com dezoito anos ou mais nessa data não terá direito.', '["Menores de dezoito anos na data da Lei têm direito, mesmo que o crime seja anterior.","Sem efeitos financeiros retroativos.","Quem já tinha dezoito anos ou mais não tem direito."]'::jsonb, '["Sem retroativos."]'::jsonb, 'A criança de oito anos, órfã por feminicídio ocorrido antes da Lei, tem direito à pensão sem receber valores passados.', '["Assertiva que paga valores retroativos à data do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pensao-regulamento' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O pagamento da pensão especial será devido a partir da data do requerimento.', '["Pagamento a partir da data do requerimento."]'::jsonb, '["Marco: data do REQUERIMENTO."]'::jsonb, 'O pedido feito em março gera pagamento a partir de março.', '["Assertiva que fixa o pagamento desde a data do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
